questionvariables.text:
/* Fonction utilitaire */
ri(a,b) := a + rand(b - a + 1) - 1;

/* Génération de l'angle (sans utiliser de liste pour éviter les bugs d'index) */
r_angle: rand(10);

if r_angle = 1 then angle: pi/6
else if r_angle = 2 then angle: pi/4
else if r_angle = 3 then angle: pi/3
else if r_angle = 4 then angle: 2*pi/3
else if r_angle = 5 then angle: 3*pi/4
else if r_angle = 6 then angle: 5*pi/6
else if r_angle = 7 then angle: 7*pi/6
else if r_angle = 8 then angle: 5*pi/4
else if r_angle = 9 then angle: 4*pi/3
else angle: 11*pi/6;

/* Génération de la fonction (séparation stricte calcul / affichage) */
r_func: rand(3);

if r_func = 1 then (
    func_calc: sin,
    func_disp: "\sin"
) else if r_func = 2 then (
    func_calc: cos,
    func_disp: "\cos"
) else (
    func_calc: tan,
    func_disp: "\tan"
);

/* Réponse attendue */
ans_correct: func_calc(angle);

/* Valeur absolue pour la correction */
val_abs: abs(func_calc(angle));

/* Calcul de l'angle de référence et du quadrant (logique entière 100% fiable) */
k: round(angle / (pi/12));
k_mod: mod(k, 12);
if k_mod = 0 then k_mod: 12;

if k_mod <= 3 then quadrant: "premier quadrant"
else if k_mod <= 6 then quadrant: "deuxième quadrant"
else if k_mod <= 9 then quadrant: "troisième quadrant"
else quadrant: "quatrième quadrant";

angle_ref_num: k_mod;
if angle_ref_num > 6 then angle_ref_num: 12 - angle_ref_num;
angle_ref: ratsimp(angle_ref_num * pi / 12);

/* Calcul du texte pour le signe */
if func_calc = cos then (
    if k_mod <= 3 or k_mod >= 10 then signe_txt: "positive"
    else signe_txt: "négative"
)
else if func_calc = sin then (
    if k_mod <= 6 then signe_txt: "positive"
    else signe_txt: "négative"
)
else (
    if k_mod <= 3 or (k_mod >= 7 and k_mod <= 9) then signe_txt: "positive"
    else signe_txt: "négative"
);

/* Erreurs classiques */
/* Erreur 1 : Oubli du signe (répond avec la valeur absolue) */
err_sign: val_abs;

/* Erreur 2 : Confusion sin/cos ou tan/cotan */
if func_calc = sin then err_swap: cos(angle)
else if func_calc = cos then err_swap: sin(angle)
else err_swap: 1/tan(angle);

/* Erreur 3 : A répondu l'angle de référence au lieu de la valeur trigonométrique */
err_angle: angle_ref;
